import requests,pathlib,datetime,hashlib,json
root=pathlib.Path(__file__).resolve().parent
urls=[('github_doc','https://raw.githubusercontent.com/OpenBMB/MiniCPM-V/main/docs/minicpm_v4dot5_en.md'),('ms_model','https://modelscope.cn/api/v1/models/OpenBMB/MiniCPM-V-4_5'),('ms_revisions','https://modelscope.cn/api/v1/models/OpenBMB/MiniCPM-V-4_5/revisions'),('ms_files_master','https://modelscope.cn/api/v1/models/OpenBMB/MiniCPM-V-4_5/repo/files?Revision=master&Recursive=true')]
res=[]
for name,url in urls:
 e={'name':name,'url':url,'requested_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'tls_verify':True}
 try:
  r=requests.get(url,timeout=(10,20));b=r.content;assert len(b)<1024*1024
  (root/(name+'.txt')).write_bytes(b);e.update(http_status=r.status_code,size_bytes=len(b),sha256=hashlib.sha256(b).hexdigest(),saved_path=str(root/(name+'.txt')))
  print(name,r.status_code,len(b),r.text[:350])
 except Exception as ex:e['error']=str(ex)[:400];print(name,e['error'])
 res.append(e)
(root/'probes.json').write_text(json.dumps(res,indent=2)+'\n')

